-- Prompt 16 (22/10/2026): demandas de várias cidades. Tabelas de cidades, órgãos públicos e roteamento por assunto,
-- colunas novas em oficios (só acrescenta; nada existente muda) e a importação das 9 cidades (planilha protocolos_cidades_v3_22out).
-- Pode rodar duas vezes: tabelas e colunas com IF NOT EXISTS, regras apagadas antes de criar, cidades e órgãos não duplicam.
-- O envio do protocolo por e-mail NÃO está aqui: fica no servidor (VPS), desligado até a Gercília escolher o e-mail.

-- ===== Parte 1: tabelas e regras =====
create table if not exists public.cidades (
  id uuid primary key default gen_random_uuid(),
  nome text not null unique,
  uf text not null default 'MG',
  prefeito text,
  porta_entrada text,
  canal_online text,
  observacao text,
  criado_em timestamptz not null default now()
);
create table if not exists public.orgaos_publicos (
  id uuid primary key default gen_random_uuid(),
  cidade_id uuid references public.cidades(id) on delete cascade,
  esfera text not null default 'municipal' check (esfera in ('municipal', 'estadual')),
  nome text not null,
  sigla text,
  assuntos text[] not null default '{}',
  responsavel text,
  email text,
  telefone text,
  endereco text,
  fonte text,
  conferido_em date,
  situacao text not null default 'ok' check (situacao in ('ok', 'conferir', 'sem_email', 'email_com_erro')),
  ativo boolean not null default true,
  criado_em timestamptz not null default now()
);
create index if not exists orgaos_publicos_cidade_idx on public.orgaos_publicos(cidade_id);
create table if not exists public.roteamento (
  id uuid primary key default gen_random_uuid(),
  cidade_id uuid not null references public.cidades(id) on delete cascade,
  categoria text not null,
  orgao_destino_id uuid references public.orgaos_publicos(id) on delete set null,
  orgao_copia_id uuid references public.orgaos_publicos(id) on delete set null,
  unique (cidade_id, categoria)
);
alter table public.oficios add column if not exists cidade text not null default 'Uberlândia';
alter table public.oficios add column if not exists esfera text not null default 'municipal';
alter table public.oficios add column if not exists orgao_destino_id uuid references public.orgaos_publicos(id) on delete set null;
alter table public.oficios add column if not exists orgao_copia_id uuid references public.orgaos_publicos(id) on delete set null;
alter table public.oficios add column if not exists email_enviado_em timestamptz;
alter table public.oficios add column if not exists email_id text;
alter table public.oficios add column if not exists email_enviado_por uuid;
alter table public.oficios add column if not exists prazo_retorno date;
alter table public.cidades enable row level security;
alter table public.orgaos_publicos enable row level security;
alter table public.roteamento enable row level security;
drop policy if exists "cidades: logado le" on public.cidades;
create policy "cidades: logado le" on public.cidades for select to authenticated using (true);
drop policy if exists "cidades: admin muda" on public.cidades;
create policy "cidades: admin muda" on public.cidades for all to authenticated using (public.is_admin(auth.uid())) with check (public.is_admin(auth.uid()));
drop policy if exists "orgaos: logado le" on public.orgaos_publicos;
create policy "orgaos: logado le" on public.orgaos_publicos for select to authenticated using (true);
drop policy if exists "orgaos: admin muda" on public.orgaos_publicos;
create policy "orgaos: admin muda" on public.orgaos_publicos for all to authenticated using (public.is_admin(auth.uid())) with check (public.is_admin(auth.uid()));
drop policy if exists "roteamento: logado le" on public.roteamento;
create policy "roteamento: logado le" on public.roteamento for select to authenticated using (true);
drop policy if exists "roteamento: admin muda" on public.roteamento;
create policy "roteamento: admin muda" on public.roteamento for all to authenticated using (public.is_admin(auth.uid())) with check (public.is_admin(auth.uid()));

-- ===== Parte 2: importação =====
-- roteamento: destino = primeiro órgão com e-mail daquele assunto; cópia = a porta de entrada da cidade (assunto geral)
select c.id, cat.categoria,
  (select o.id from public.orgaos_publicos o where o.cidade_id = c.id and o.esfera = 'municipal' and cat.categoria = any(o.assuntos) and o.email is not null order by o.criado_em limit 1),
  (select o.id from public.orgaos_publicos o where o.cidade_id = c.id and o.esfera = 'municipal' and 'geral' = any(o.assuntos) and o.email is not null order by o.criado_em limit 1)
from public.cidades c
cross join (select distinct unnest(assuntos) as categoria from public.orgaos_publicos) cat
where cat.categoria <> 'geral'
on conflict (cidade_id, categoria) do nothing;

-- Conferência: 9 cidades, 190 órgãos municipais e 57 estaduais
select c.nome, count(*) filter (where o.esfera = 'municipal') as municipais, count(*) filter (where o.esfera = 'estadual') as estaduais, count(o.email) as com_email
from public.cidades c left join public.orgaos_publicos o on o.cidade_id = c.id group by c.nome order by c.nome;
