insert into public.cidades (nome, porta_entrada, canal_online, observacao) values ('Uberaba', 'segov.ura@gmail.com (Secretaria de Governo)', 'e-Ouv: sistema.ouvidorias.gov.br/publico/MG/Uberaba', 'Todas as secretarias têm e-mail no site. Vários são Gmail, mas são os publicados oficialmente.') on conflict (nome) do nothing;
