insert into public.cidades (nome, porta_entrada, canal_online, observacao) values ('Araxá', 'prefeito@araxa.mg.gov.br (Gabinete do Prefeito)', 'Protocolo online: servidor.araxa.mg.gov.br/protocolo', 'Meio Ambiente usa o e-mail do IPDSA; Gestão aparece com o mesmo e-mail da Fazenda (conferir).') on conflict (nome) do nothing;
insert into public.cidades (nome, porta_entrada, canal_online, observacao) values ('Patos de Minas', 'gabinete@patosdeminas.mg.gov.br (Secretaria de Governo)', 'Consulta de protocolo: servicos.patosdeminas.mg.gov.br', 'Saúde sem secretário informado no site.') on conflict (nome) do nothing;
insert into public.cidades (nome, porta_entrada, canal_online, observacao) values ('Ituiutaba', 'secretario.governo@ituiutaba.mg.gov.br (Secretaria de Governo)', 'Fala Cidadão: sistemas.ituiutaba.mg.gov.br/falacidadao', 'Padrão de e-mail: secretario.<área>@ituiutaba.mg.gov.br.') on conflict (nome) do nothing;
insert into public.cidades (nome, porta_entrada, canal_online, observacao) values ('Tupaciguara', 'governo@tupaciguara.mg.gov.br (Secretaria Municipal de Governo)', 'Não achei protocolo online', 'Abaixo de 100 mil habitantes, entra por pedido seu.') on conflict (nome) do nothing;
insert into public.cidades (nome, porta_entrada, canal_online, observacao) values ('Patrocínio', 'Sem e-mail público do gabinete', 'Não achei protocolo online', 'O site não publica e-mail do gabinete. Editais oficiais trazem sec.administracao@ e meioambiente@patrocinio.mg.gov.br. O resto: ligar (34) 3839-1800.') on conflict (nome) do nothing;
insert into public.cidades (nome, porta_entrada, canal_online, observacao) values ('Juiz de Fora', 'governo@pjf.mg.gov.br (Secretaria de Governo)', 'Ouvidoria: pjf.mg.gov.br/transparencia/ouvidoria', 'Site lido em 20/10 (página "atendimento" de cada secretaria). O gabinete da prefeita não publica e-mail: mandar pra SG, telefone (32) 3690-7115. Obras e Mobilidade não publicam e-mail.') on conflict (nome) do nothing;
insert into public.cidades (nome, porta_entrada, canal_online, observacao) values ('Belo Horizonte', 'gabpref@pbh.gov.br (Gabinete do Prefeito) e smgo@pbh.gov.br (Secretaria de Governo)', '156 e Portal de Serviços: servicos.pbh.gov.br', 'Contatos do CSV oficial da estrutura (Portal de Dados Abertos, 01/10/2026). A SMGO tem Subsecretaria para Assuntos Parlamentares e de Emendas Parlamentares. Subprefeituras sem contato no CSV.') on conflict (nome) do nothing;
